package push

import (
	"bytes"
	"context"
	"encoding/json"
	"fmt"
	"io"
	"net/http"
	"os"
	"sync"
	"time"

	"golang.org/x/oauth2"
	"golang.org/x/oauth2/google"
)

var (
	once    sync.Once
	ts      oauth2.TokenSource
	project string
	initErr error
	client  = &http.Client{Timeout: 10 * time.Second}
)

func setup() {
	creds, err := google.CredentialsFromJSONWithType(context.Background(),
		[]byte(os.Getenv("FCM_SERVICE_ACCOUNT_JSON")), google.ServiceAccount,
		"https://www.googleapis.com/auth/firebase.messaging")
	if err != nil {
		initErr = fmt.Errorf("FCM_SERVICE_ACCOUNT_JSON: %w", err)
		return
	}
	ts, project = creds.TokenSource, creds.ProjectID
}

// Send delivers a high-priority data message. Short TTL: a dial command
// that arrives minutes late must not ring someone.
func Send(ctx context.Context, token string, data map[string]string) error {
	once.Do(setup)
	if initErr != nil {
		return initErr
	}
	tok, err := ts.Token()
	if err != nil {
		return err
	}
	body, _ := json.Marshal(map[string]any{"message": map[string]any{
		"token":   token,
		"data":    data,
		"android": map[string]any{"priority": "HIGH", "ttl": "30s"},
	}})
	req, _ := http.NewRequestWithContext(ctx, http.MethodPost,
		"https://fcm.googleapis.com/v1/projects/"+project+"/messages:send", bytes.NewReader(body))
	req.Header.Set("Authorization", "Bearer "+tok.AccessToken)
	req.Header.Set("Content-Type", "application/json")
	resp, err := client.Do(req)
	if err != nil {
		return err
	}
	defer resp.Body.Close()
	if resp.StatusCode != http.StatusOK {
		b, _ := io.ReadAll(io.LimitReader(resp.Body, 1024))
		return fmt.Errorf("fcm %d: %s", resp.StatusCode, b)
	}
	return nil
}

