package server

import (
	"context"
	"encoding/json"
	"errors"
	"log"
	"net/http"
	"regexp"
	"strconv"
	"strings"
	"time"

	"github.com/jackc/pgx/v5"
	"github.com/jackc/pgx/v5/pgxpool"

	"paytmcall/internal/auth"
	"paytmcall/internal/db"
	"paytmcall/internal/push"
)

var (
	phoneRe = regexp.MustCompile(`^\+91\d{10}$`)
	uuidRe  = regexp.MustCompile(`^[0-9a-fA-F-]{36}$`)
	// Statuses the Android helper may report for a SIM call.
	deviceStatuses = map[string]bool{"dialing": true, "ended": true, "failed": true}
)

func New() http.Handler {
	mux := http.NewServeMux()
	mux.HandleFunc("POST /api/signup", signup)
	mux.HandleFunc("POST /api/login", login)
	mux.HandleFunc("POST /api/devices", authed(registerDevice))
	mux.HandleFunc("POST /api/dial", authed(dial))
	mux.HandleFunc("GET /api/calls", authed(listCalls))
	mux.HandleFunc("GET /api/calls/{id}", authed(getCall))
	mux.HandleFunc("POST /api/calls/{id}", authed(updateCall))
	return mux
}

type handler func(w http.ResponseWriter, r *http.Request, pool *pgxpool.Pool, userID string)

func authed(h handler) http.HandlerFunc {
	return func(w http.ResponseWriter, r *http.Request) {
		tok, ok := strings.CutPrefix(r.Header.Get("Authorization"), "Bearer ")
		if !ok {
			fail(w, http.StatusUnauthorized, "unauthorized")
			return
		}
		uid, err := auth.Parse(tok)
		if err != nil {
			fail(w, http.StatusUnauthorized, "unauthorized")
			return
		}
		pool, err := db.Pool()
		if err != nil {
			serverErr(w, err)
			return
		}
		h(w, r, pool, uid)
	}
}

type credentials struct {
	Email    string `json:"email"`
	Password string `json:"password"`
}

func (c *credentials) normalize() string {
	c.Email = strings.ToLower(strings.TrimSpace(c.Email))
	if !strings.Contains(c.Email, "@") || len(c.Email) > 254 {
		return "invalid email"
	}
	if len(c.Password) < 8 || len(c.Password) > 72 { // bcrypt reads at most 72 bytes
		return "password must be 8-72 characters"
	}
	return ""
}

func signup(w http.ResponseWriter, r *http.Request) {
	var in credentials
	if !decode(w, r, &in) {
		return
	}
	if msg := in.normalize(); msg != "" {
		fail(w, http.StatusBadRequest, msg)
		return
	}
	pool, err := db.Pool()
	if err != nil {
		serverErr(w, err)
		return
	}
	hash, err := auth.Hash(in.Password)
	if err != nil {
		serverErr(w, err)
		return
	}
	var id string
	err = pool.QueryRow(r.Context(),
		`insert into users (email, password_hash) values ($1, $2)
		 on conflict (email) do nothing returning id`, in.Email, hash).Scan(&id)
	if errors.Is(err, pgx.ErrNoRows) {
		fail(w, http.StatusConflict, "email already registered")
		return
	}
	if err != nil {
		serverErr(w, err)
		return
	}
	issueToken(w, http.StatusCreated, id)
}

func login(w http.ResponseWriter, r *http.Request) {
	var in credentials
	if !decode(w, r, &in) {
		return
	}
	if in.normalize() != "" {
		fail(w, http.StatusUnauthorized, "wrong email or password")
		return
	}
	pool, err := db.Pool()
	if err != nil {
		serverErr(w, err)
		return
	}
	var id, hash string
	err = pool.QueryRow(r.Context(),
		`select id, password_hash from users where email = $1`, in.Email).Scan(&id, &hash)
	if err != nil && !errors.Is(err, pgx.ErrNoRows) {
		serverErr(w, err)
		return
	}
	if err != nil || !auth.Check(hash, in.Password) {
		fail(w, http.StatusUnauthorized, "wrong email or password")
		return
	}
	issueToken(w, http.StatusOK, id)
}

func issueToken(w http.ResponseWriter, status int, userID string) {
	tok, err := auth.Issue(userID)
	if err != nil {
		serverErr(w, err)
		return
	}
	reply(w, status, map[string]string{"token": tok})
}

// ponytail: one device per user; newest registration replaces older ones.
func registerDevice(w http.ResponseWriter, r *http.Request, pool *pgxpool.Pool, uid string) {
	var in struct {
		FCMToken string `json:"fcm_token"`
	}
	if !decode(w, r, &in) {
		return
	}
	if in.FCM[redacted] "" || len(in.FCMToken) > 4096 {
		fail(w, http.StatusBadRequest, "fcm_token required")
		return
	}
	_, err := pool.Exec(r.Context(),
		`with gone as (delete from devices where user_id = $1 and fcm_token <> $2)
		 insert into devices (user_id, fcm_token) values ($1, $2)
		 on conflict (fcm_token) do update set user_id = excluded.user_id, updated_at = now()`,
		uid, in.FCMToken)
	if err != nil {
		serverErr(w, err)
		return
	}
	w.WriteHeader(http.StatusNoContent)
}

func dial(w http.ResponseWriter, r *http.Request, pool *pgxpool.Pool, uid string) {
	var in struct {
		To string `json:"to"`
	}
	if !decode(w, r, &in) {
		return
	}
	if !phoneRe.MatchString(in.To) {
		fail(w, http.StatusBadRequest, "number must look like +91XXXXXXXXXX")
		return
	}
	ctx := r.Context()
	var fcmToken string
	err := pool.QueryRow(ctx,
		`select fcm_token from devices where user_id = $1 order by updated_at desc limit 1`, uid).Scan(&fcmToken)
	if errors.Is(err, pgx.ErrNoRows) {
		fail(w, http.StatusConflict, "no phone linked: sign in on the Android helper app first")
		return
	}
	if err != nil {
		serverErr(w, err)
		return
	}
	var id string
	err = pool.QueryRow(ctx,
		`insert into calls (user_id, mode, to_number) values ($1, 'sim', $2) returning id`, uid, in.To).Scan(&id)
	if err != nil {
		serverErr(w, err)
		return
	}
	err = push.Send(ctx, fcmToken, map[string]string{
		"type":    "dial",
		"call_id": id,
		"to":      in.To,
		"sent_at": strconv.FormatInt(time.Now().Unix(), 10),
	})
	if err != nil {
		log.Printf("push: %v", err)
		markFailed(pool, id)
		fail(w, http.StatusBadGateway, "could not reach your phone")
		return
	}
	reply(w, http.StatusCreated, map[string]string{"id": id})
}

func markFailed(pool *pgxpool.Pool, id string) {
	ctx, cancel := context.WithTimeout(context.Background(), 5*time.Second)
	defer cancel()
	if _, err := pool.Exec(ctx, `update calls set status = 'failed', ended_at = now() where id = $1`, id); err != nil {
		log.Printf("mark failed: %v", err)
	}
}

type call struct {
	ID        string     `json:"id"`
	Mode      string     `json:"mode"`
	To        string     `json:"to"`
	Status    string     `json:"status"`
	DurationS int        `json:"duration_s"`
	Price     *float64   `json:"price,omitempty"`
	CreatedAt time.Time  `json:"created_at"`
	EndedAt   *time.Time `json:"ended_at,omitempty"`
}

const callCols = `id, mode, to_number, status, duration_s, price, created_at, ended_at`

func scanCall(row pgx.Row) (call, error) {
	var c call
	err := row.Scan(&c.ID, &c.Mode, &c.To, &c.Status, &c.DurationS, &c.Price, &c.CreatedAt, &c.EndedAt)
	return c, err
}

func listCalls(w http.ResponseWriter, r *http.Request, pool *pgxpool.Pool, uid string) {
	rows, err := pool.Query(r.Context(),
		`select `+callCols+` from calls where user_id = $1 order by created_at desc limit 50`, uid)
	if err != nil {
		serverErr(w, err)
		return
	}
	defer rows.Close()
	calls := []call{}
	for rows.Next() {
		c, err := scanCall(rows)
		if err != nil {
			serverErr(w, err)
			return
		}
		calls = append(calls, c)
	}
	if err := rows.Err(); err != nil {
		serverErr(w, err)
		return
	}
	reply(w, http.StatusOK, calls)
}

func getCall(w http.ResponseWriter, r *http.Request, pool *pgxpool.Pool, uid string) {
	id := r.PathValue("id")
	if !uuidRe.MatchString(id) {
		fail(w, http.StatusNotFound, "not found")
		return
	}
	c, err := scanCall(pool.QueryRow(r.Context(),
		`select `+callCols+` from calls where id = $1 and user_id = $2`, id, uid))
	if errors.Is(err, pgx.ErrNoRows) {
		fail(w, http.StatusNotFound, "not found")
		return
	}
	if err != nil {
		serverErr(w, err)
		return
	}
	reply(w, http.StatusOK, c)
}

func updateCall(w http.ResponseWriter, r *http.Request, pool *pgxpool.Pool, uid string) {
	id := r.PathValue("id")
	var in struct {
		Status    string `json:"status"`
		DurationS int    `json:"duration_s"`
	}
