package com.laptopdialer

import android.content.Intent
import android.net.Uri
import android.os.Bundle
import android.telecom.TelecomManager
import com.google.firebase.messaging.FirebaseMessagingService
import com.google.firebase.messaging.RemoteMessage

private val PHONE = Regex("""^\+91\d{10}$""")

// Firebase calls these on a background thread.
class PushService : FirebaseMessagingService() {

    override fun onNewToken([redacted] {
        runCatching { Api.registerDevice(this, token) }
    }

    override fun onMessageReceived(msg: RemoteMessage) {
        val d = msg.data
        if (d["type"] != "dial" || Api.jwt(this) == null) return
        val callId = d["call_id"] ?: return
        val to = d["to"] ?: return
        if (!PHONE.matches(to)) {
            Api.report(this, callId, "failed")
            return
        }
        val startedAt = System.currentTimeMillis()
        try {
            getSystemService(TelecomManager::class.java)
                .placeCall(Uri.fromParts("tel", to, null), Bundle())
        } catch (e: SecurityException) { // CALL_PHONE not granted
            Api.report(this, callId, "failed")
            return
        }
        Api.report(this, callId, "dialing")
        startForegroundService(
            Intent(this, CallWatchService::class.java)
                .putExtra("call_id", callId)
                .putExtra("to", to)
                .putExtra("started_at", startedAt)
        )
    }
}

