package com.laptopdialer

import android.app.Notification
import android.app.NotificationChannel
import android.app.NotificationManager
import android.app.Service
import android.content.Intent
import android.content.pm.ServiceInfo
import android.provider.CallLog
import kotlin.concurrent.thread

private const val POLL_MS = 3_000L
private const val MAX_WAIT_MS = 3 * 60 * 60 * 1000L

// Waits for the call to land in the call log (written when it ends), then reports its duration.
class CallWatchService : Service() {

    override fun onBind(intent: Intent?) = null

    override fun onStartCommand(intent: Intent?, flags: Int, startId: Int): Int {
        startForeground(1, notification(), ServiceInfo.FOREGROUND_SERVICE_TYPE_PHONE_CALL)
        val callId = intent?.getStringExtra("call_id")
        val to = intent?.getStringExtra("to")
        val startedAt = intent?.getLongExtra("started_at", 0L) ?: 0L
        if (callId == null || to == null) {
            stopSelf(startId)
            return START_NOT_STICKY
        }
        thread {
            Api.report(this, callId, "ended", waitForDuration(to, startedAt) ?: 0)
            stopSelf(startId)
        }
        return START_NOT_STICKY
    }

    // ponytail: polls the call log every 3s; switch to TelephonyCallback if battery cost shows up.
    private fun waitForDuration(to: String, since: Long): Int? {
        val last10 = to.takeLast(10)
        val deadline = since + MAX_WAIT_MS
        while (System.currentTimeMillis() < deadline) {
            Thread.sleep(POLL_MS)
            try {
                contentResolver.query(
                    CallLog.Calls.CONTENT_URI,
                    arrayOf(CallLog.Calls.NUMBER, CallLog.Calls.DURATION),
                    "${CallLog.Calls.TYPE} = ? AND ${CallLog.Calls.DATE} >= ?",
                    arrayOf(CallLog.Calls.OUTGOING_TYPE.toString(), (since - 5_000).toString()),
                    "${CallLog.Calls.DATE} DESC",
                )?.use { c ->
                    // Call log may store the number as +91…, 0…, or bare 10 digits.
                    while (c.moveToNext()) {
                        if (c.getString(0).orEmpty().filter(Char::isDigit).endsWith(last10)) return c.getInt(1)
                    }
                }
            } catch (e: SecurityException) { // READ_CALL_LOG denied
                return null
            }
        }
        return null
    }

    private fun notification(): Notification {
        val nm = getSystemService(NotificationManager::class.java)
        nm.createNotificationChannel(NotificationChannel("call", "Active call", NotificationManager.IMPORTANCE_LOW))
        return Notification.Builder(this, "call")
            .setSmallIcon(android.R.drawable.sym_action_call)
            .setContentTitle("Call from laptop in progress")
            .build()
    }
}

