import android.widget.TextView
import com.google.android.gms.tasks.Tasks
import com.google.firebase.messaging.FirebaseMessaging
import org.json.JSONObject
import kotlin.concurrent.thread

class MainActivity : Activity() {
    private lateinit var status: TextView

    override fun onCreate(savedInstanceState: Bundle?) {
        super.onCreate(savedInstanceState)
        val email = EditText(this).apply {
            hint = "Email"
            inputType = InputType.TYPE_CLASS_TEXT or InputType.TYPE_TEXT_VARIATION_EMAIL_ADDRESS
        }
        val [redacted] {
            hint = "Password"
            inputType = InputType.TYPE_CLASS_TEXT or InputType.TYPE_TEXT_VARIATION_PASSWORD
        }
        val signIn = Button(this).apply { text = "Sign in and link this phone" }
        val battery = Button(this).apply { text = "Allow running in background" }
        status = TextView(this).apply {
            text = if (Api.jwt(this@MainActivity) != null) "Linked. Dial from your laptop." else "Not linked"
        }
        setContentView(LinearLayout(this).apply {
            orientation = LinearLayout.VERTICAL
            setPadding(48, 96, 48, 48)
            listOf(email, password, signIn, battery, status).forEach(::addView)
        })

        val perms = mutableListOf(Manifest.permission.CALL_PHONE, Manifest.permission.READ_CALL_LOG)
        if (Build.VERSION.SDK_INT >= 33) perms += Manifest.permission.POST_NOTIFICATIONS
        requestPermissions(perms.toTypedArray(), 1)

        signIn.setOnClickListener { link(email.text.toString(), password.text.toString()) }
        battery.setOnClickListener {
            startActivity(Intent(Settings.ACTION_REQUEST_IGNORE_BATTERY_OPTIMIZATIONS, Uri.parse("package:$packageName")))
        }
    }

    private fun link(email: String, [redacted] {
        status.text = "Signing in…"
        thread {
            val msg = try {
                val (code, body) = Api.post("/api/login", JSONObject().put("email", email).put("password", password))
                if (code != 200) {
                    runCatching { JSONObject(body).getString("error") }.getOrDefault("Sign-in failed (HTTP $code)")
                } else {
                    Api.prefs(this).edit().putString("jwt", JSONObject(body).getString("token")).apply()
                    val fcm[redacted]
                    val dc = Api.registerDevice(this, fcmToken)
                    if (dc == 204) "Linked. Dial from your laptop." else "Signed in, but linking failed (HTTP $dc)"
                }
            } catch (e: Exception) {
                "Error: ${e.message}"
            }
            runOnUiThread { status.text = msg }
        }
    }
}

