import {FormEvent, useEffect, useState} from 'react';
import {Dial, GetCall, ListCalls, LoggedIn, Login, Logout, Signup} from '../wailsjs/go/main/App';
import {main} from '../wailsjs/go/models';

type Call = main.Call;

const POLL_MS = 2000;
const QUEUED_TIMEOUT_MS = 40_000; // FCM drops the push after 30s

const errMsg = (e: unknown) => (typeof e === 'string' ? e : e instanceof Error ? e.message : String(e));
const fmtDuration = (s: number) => `${Math.floor(s / 60)}:${String(s % 60).padStart(2, '0')}`;
const fmtTime = (t: string) => new Date(t).toLocaleString('en-IN', {dateStyle: 'medium', timeStyle: 'short'});

function describe(c: Call, stale: boolean): string {
    if (stale) return "Your phone didn't respond. Check it's online and the helper app is signed in.";
    switch (c.status) {
        case 'queued': return 'Sending to your phone…';
        case 'dialing': return 'Calling from your phone. Talk on the phone.';
        case 'ended': return c.duration_s > 0 ? `Ended · ${fmtDuration(c.duration_s)}` : 'Not answered or cancelled';
        case 'failed': return 'Call failed';
        default: return c.status;
    }
}

export default function App() {
    const [loggedIn, setLoggedIn] = useState<boolean | null>(null);
    useEffect(() => { LoggedIn().then(setLoggedIn); }, []);
    if (loggedIn === null) return null;
    return loggedIn
        ? <Dialer onSignedOut={() => setLoggedIn(false)}/>
        : <SignIn onSignedIn={() => setLoggedIn(true)}/>;
}

function SignIn({onSignedIn}: {onSignedIn: () => void}) {
    const [email, setEmail] = useState('');
    const [password, setPassword] = useState('');
    const [error, setError] = useState('');
    const [busy, setBusy] = useState(false);

    async function submit(e: FormEvent, create: boolean) {
        e.preventDefault();
        setBusy(true);
        setError('');
        try {
            await (create ? Signup : Login)(email, password);
            onSignedIn();
        } catch (err) {
            setError(errMsg(err));
        } finally {
            setBusy(false);
        }
    }

    return (
        <main>
            <h1>Laptop Dialer</h1>
            <p className="muted">Use the same account in the Android helper app on your phone.</p>
            <form onSubmit={e => submit(e, false)}>
                <label>Email
                    <input type="email" required autoComplete="username" value={email}
                           onChange={e => setEmail(e.target.value)}/>
                </label>
                <label>Password
                    <input type="password" required minLength={8} maxLength={72} autoComplete="current-password"
                           value={password} onChange={e => setPassword(e.target.value)}/>
                </label>
                {error && <p className="error" role="alert">{error}</p>}
                <button className="primary" disabled={busy}>Sign in</button>
                <button type="button" className="link" disabled={busy} onClick={e => submit(e, true)}>
                    Create account
                </button>
            </form>
        </main>
    );
}

function Dialer({onSignedOut}: {onSignedOut: () => void}) {
    const [number, setNumber] = useState('');
    const [active, setActive] = useState<Call | null>(null);
    const [stale, setStale] = useState(false);
    const [error, setError] = useState('');
    const [history, setHistory] = useState<Call[]>([]);

    const handle = (e: unknown) => {
        const m = errMsg(e);
        if (m === 'signed out') onSignedOut();
        else setError(m);
    };
    const refresh = () => ListCalls().then(cs => setHistory(cs ?? [])).catch(handle);
    useEffect(() => { refresh(); }, []);

    const activeId = active?.id;
    const finished = !!active?.ended_at || stale;
    useEffect(() => {
        if (!activeId || finished) return;
        const started = Date.now();
        const timer = setInterval(async () => {
            try {
                const c = await GetCall(activeId);
                setActive(c);
                if (c.ended_at) refresh();
                else if (c.status === 'queued' && Date.now() - started > QUEUED_TIMEOUT_MS) setStale(true);
            } catch (e) {
                handle(e);
            }
        }, POLL_MS);
        return () => clearInterval(timer);
    }, [activeId, finished]);

    async function call(e: FormEvent) {
        e.preventDefault();
        setError('');
        setStale(false);
        try {
            const id = await Dial(number);
            setActive(await GetCall(id));
        } catch (err) {
            handle(err);
        }
    }

    const busy = !!active && !finished;

    return (
        <main>
            <header>
                <h1>Laptop Dialer</h1>
                <button className="link" onClick={() => Logout().then(onSignedOut)}>Sign out</button>
            </header>

            <form onSubmit={call} className="dialer">
                <label>Phone number
                    <div className="number">
                        <span>+91</span>
                        <input type="tel" inputMode="tel" required autoFocus placeholder="[redacted]"
                               value={number} onChange={e => setNumber(e.target.value)} disabled={busy}/>
                    </div>
                </label>
                <button className="primary call" disabled={busy}>{busy ? 'Calling…' : 'Call from my phone'}</button>
                {error && <p className="error" role="alert">{error}</p>}
            </form>

            {active && (
                <section className={`status ${busy ? 'live' : ''}`} aria-live="polite">
                    <strong>{active.to}</strong>
                    <span>{describe(active, stale)}</span>
                </section>
            )}

            <h2>Recent calls</h2>
            {history.length === 0 && <p className="muted">No calls yet.</p>}
            <ul className="history">
                {history.map(c => (
                    <li key={c.id}>
                        <button className="row" onClick={() => setNumber(c.to.replace(/^\+91/, ''))} disabled={busy}>
                            <span>{c.to}<small>{fmtTime(c.created_at)}</small></span>
                            <span className="muted">
                                {c.status === 'ended' ? (c.duration_s > 0 ? fmtDuration(c.duration_s) : 'No answer') : c.status}
                            </span>
                        </button>
                    </li>
                ))}
            </ul>
        </main>
    );
}

