      if (!userId) return new Response("unauthorized", { status: 401 });
      return env.PHONES.get(env.PHONES.idFromName(userId)).fetch(req);
    }

    // The Go API (server-to-server) asks us to forward a dial command.
    if (url.pathname === "/dial" && req.method === "POST") {
      if (!secretMatches(req.headers.get("Authorization") ?? "", env.RELAY_SECRET)) {
        return new Response("unauthorized", { status: 401 });
      }
      const body = await req.json<{ user_id?: unknown; call_id?: unknown; to?: unknown }>().catch(() => null);
      const { user_id, call_id, to } = body ?? {};
      if (typeof user_id !== "string" || !UUID.test(user_id) || typeof call_id !== "string" || !UUID.test(call_id)
