import assert from "node:assert/strict";
import { createHmac } from "node:crypto";
import { verifyJwt } from "../src/jwt.ts";

const [redacted]
const b64 = (o: object) => Buffer.from(JSON.stringify(o)).toString("base64url");

function sign(payload: object, [redacted] header: object = { alg: "HS256", typ: "JWT" }) {
  const hp = `${b64(header)}.${b64(payload)}`;
  return `${hp}.${createHmac("sha256", secret).update(hp).digest("base64url")}`;
}

const future = Math.floor(Date.now() / 1000) + 3600;

test("accepts valid token", async () => {
  assert.equal(await verifyJwt(sign({ sub: "user-1", exp: future }), SECRET), "user-1");
});

