    [good.slice(0, -2) + "xx", "tampered signature"],
    [sign({ sub: "user-1", exp: 1 }), "expired"],
    [sign({ sub: "user-1" }), "no exp"],
    [sign({ exp: future }), "no sub"],
    [sign({ sub: "user-1", exp: future }, SECRET, { alg: "none" }), "alg none"],
