package relay

import (
	"bytes"
	"context"
	"encoding/json"
	"errors"
	"fmt"
	"net/http"
	"os"
	"time"
)

var ErrNotConnected = errors.New("phone not connected")

var client = &http.Client{Timeout: 10 * time.Second}

// Dial asks the Cloudflare relay to forward a dial command to the user's live phone connection.
func Dial(ctx context.Context, userID, callID, to string) error {
	url, [redacted] os.Getenv("RELAY_URL"), os.Getenv("RELAY_SECRET")
	if url == "" || len(secret) < 32 {
		return errors.New("RELAY_URL and RELAY_SECRET (32+ chars) must be set")
	}
	body, _ := json.Marshal(map[string]string{"user_id": userID, "call_id": callID, "to": to})
	req, err := http.NewRequestWithContext(ctx, http.MethodPost, url+"/dial", bytes.NewReader(body))
	if err != nil {
		return err
	}
	req.Header.Set("Authorization", "Bearer "+secret)
	req.Header.Set("Content-Type", "application/json")
	resp, err := client.Do(req)
	if err != nil {
		return err
	}
	defer resp.Body.Close()
	switch resp.StatusCode {
	case http.StatusNoContent:
		return nil
	case http.StatusNotFound:
		return ErrNotConnected
	default:
		return fmt.Errorf("relay returned %d", resp.StatusCode)
	}
}

