	"net/http/httptest"
	"strings"
	"testing"

	"paytmcall/internal/auth"
)

func TestPhoneValidation(t *testing.T) {
	for num, want := range map[string]bool{
		"[redacted]":  true,
		"[redacted]":     false,
		"+91987654321":   false,
		"+9198765432100": false,
		"+14155550100":   false,
		"[redacted]a":  false,
	} {
		if got := phoneRe.MatchString(num); got != want {
			t.Errorf("%s: got %v want %v", num, got, want)
		}
	}
}

func TestTokenRoundTrip(t *testing.T) {
	t.Setenv("JWT_SECRET", strings.Repeat("k", 32))
	tok, err := auth.Issue("user-1")
	if err != nil {
		t.Fatal(err)
	}
	if uid, err := auth.Parse(tok); err != nil || uid != "user-1" {
		t.Fatalf("parse: %q %v", uid, err)
	}
	if _, err := auth.Parse(tok[:len(tok)-2] + "xx"); err == nil {
		t.Fatal("tampered token accepted")
	}
	t.Setenv("JWT_SECRET", strings.Repeat("z", 32))
	if _, err := auth.Parse(tok); err == nil {
		t.Fatal("token signed with other secret accepted")
	}
	t.Setenv("JWT_SECRET", "short")
	if _, err := auth.Issue("u"); err == nil {
		t.Fatal("short secret accepted")
	}
}

func TestProtectedRoutesRejectMissingToken(t *testing.T) {
	t.Setenv("JWT_SECRET", strings.Repeat("k", 32))
	h := New()
	for _, rt := range []string{"POST /api/dial", "GET /api/calls", "POST /api/devices", "GET /api/calls/x"} {
		method, path, _ := strings.Cut(rt, " ")
		for _, header := range []string{"", "Bearer garbage"} {
			req := httptest.NewRequest(method, path, strings.NewReader(`{}`))
			if header != "" {
				req.Header.Set("Authorization", header)
			}
			rec := httptest.NewRecorder()
			h.ServeHTTP(rec, req)
			if rec.Code != http.StatusUnauthorized {
				t.Errorf("%s with %q: got %d", rt, header, rec.Code)
			}
		}
	}
}

