package com.laptopdialer

import android.app.Notification
import android.app.NotificationChannel
import android.app.NotificationManager
import android.app.PendingIntent
import android.app.Service
import android.content.Intent
import android.content.pm.ServiceInfo
import android.net.Uri
import android.os.Build
import android.os.Bundle
import android.os.Handler
import android.os.Looper
import android.provider.CallLog
import android.telecom.TelecomManager
import okhttp3.OkHttpClient
import okhttp3.Request
import okhttp3.Response
import okhttp3.WebSocket
import okhttp3.WebSocketListener
import org.json.JSONObject
import java.util.concurrent.TimeUnit
import kotlin.concurrent.thread

private val PHONE = Regex("""^\+91\d{10}$""")
private const val INITIAL_BACKOFF_MS = 2_000L
private const val MAX_BACKOFF_MS = 60_000L
private const val POLL_MS = 3_000L
private const val MAX_CALL_WAIT_MS = 3 * 60 * 60 * 1000L
private const val CLOSE_REPLACED = 4000

// Always-on: holds the WebSocket to the Cloudflare relay, places calls it receives, reports results.
class RelayService : Service() {
    private val client = OkHttpClient.Builder().pingInterval(30, TimeUnit.SECONDS).build()
    private val main = Handler(Looper.getMainLooper())
    @Volatile private var socket: WebSocket? = null
    @Volatile private var replaced = false
    private var backoffMs = INITIAL_BACKOFF_MS
    private var stopped = false

    override fun onBind(intent: Intent?) = null

    override fun onStartCommand(intent: Intent?, flags: Int, startId: Int): Int {
        val n = notification("Connecting…")
        if (Build.VERSION.SDK_INT >= 34) {
            startForeground(1, n, ServiceInfo.FOREGROUND_SERVICE_TYPE_REMOTE_MESSAGING)
        } else {
            startForeground(1, n)
        }
        if (socket == null) connect()
        return START_STICKY
    }

    override fun onDestroy() {
        stopped = true
        main.removeCallbacksAndMessages(null)
        socket?.close(1000, null)
    }

    // Always called on the main thread.
    private fun connect() {
        val jwt = Api.jwt(this) ?: return stopSelf()
        replaced = false
        val req = Request.Builder()
            .url(BuildConfig.RELAY_URL + "/phone")
            .header("Authorization", "Bearer $jwt")
            .build()
        socket = client.newWebSocket(req, object : WebSocketListener() {
            override fun onOpen(ws: WebSocket, response: Response) {
                main.post { backoffMs = INITIAL_BACKOFF_MS }
                show("Ready: dial from your laptop")
            }

            override fun onMessage(ws: WebSocket, text: String) {
                thread { handle(text) }
            }

            override fun onClosing(ws: WebSocket, code: Int, reason: String) {
                if (code == CLOSE_REPLACED) replaced = true
                ws.close(1000, null)
            }

            override fun onClosed(ws: WebSocket, code: Int, reason: String) {
                main.post { if (replaced) stopWith("Another phone is now linked") else retry(ws) }
            }

            override fun onFailure(ws: WebSocket, t: Throwable, response: Response?) {
                main.post {
                    if (response?.code == 401) {
                        Api.prefs(this@RelayService).edit().remove("jwt").apply()
                        stopWith("Signed out: open the app and sign in again")
                    } else {
                        retry(ws)
                    }
                }
            }
        })
    }

    private fun retry(ws: WebSocket) {
        if (stopped || ws !== socket) return
        socket = null
        show("Reconnecting…")
        main.postDelayed({ if (!stopped && socket == null) connect() }, backoffMs)
        backoffMs = (backoffMs * 2).coerceAtMost(MAX_BACKOFF_MS)
    }

    private fun stopWith(message: String) {
        stopped = true
        getSystemService(NotificationManager::class.java).notify(2, notification(message, ongoing = false))
        stopSelf()
    }

    // Runs on a worker thread.
    private fun handle(text: String) {
        val msg = runCatching { JSONObject(text) }.getOrNull() ?: return
        if (msg.optString("type") != "dial") return
        val callId = msg.optString("call_id").ifEmpty { return }
        val to = msg.optString("to")
        if (!PHONE.matches(to)) return Api.report(this, callId, "failed")
        val startedAt = System.currentTimeMillis()
        try {
            getSystemService(TelecomManager::class.java).placeCall(Uri.fromParts("tel", to, null), Bundle())
        } catch (e: SecurityException) { // CALL_PHONE not granted
            return Api.report(this, callId, "failed")
        }
        Api.report(this, callId, "dialing")
        Api.report(this, callId, "ended", waitForDuration(to, startedAt) ?: 0)
    }

    // The call log entry appears when the call ends.
    // ponytail: polls every 3s; switch to TelephonyCallback if battery cost shows up.
    private fun waitForDuration(to: String, since: Long): Int? {
        val last10 = to.takeLast(10)
        val deadline = since + MAX_CALL_WAIT_MS
        while (System.currentTimeMillis() < deadline) {
            Thread.sleep(POLL_MS)
            try {
                contentResolver.query(
                    CallLog.Calls.CONTENT_URI,
                    arrayOf(CallLog.Calls.NUMBER, CallLog.Calls.DURATION),
                    "${CallLog.Calls.TYPE} = ? AND ${CallLog.Calls.DATE} >= ?",
                    arrayOf(CallLog.Calls.OUTGOING_TYPE.toString(), (since - 5_000).toString()),
                    "${CallLog.Calls.DATE} DESC",
                )?.use { c ->
                    // Stored as +91…, 0…, or bare 10 digits depending on the phone.
                    while (c.moveToNext()) {
                        if (c.getString(0).orEmpty().filter(Char::isDigit).endsWith(last10)) return c.getInt(1)
                    }
                }
            } catch (e: SecurityException) { // READ_CALL_LOG denied
                return null
            }
        }
        return null
    }

    private fun show(text: String) {
        getSystemService(NotificationManager::class.java).notify(1, notification(text))
    }

    private fun notification(text: String, ongoing: Boolean = true): Notification {
        val nm = getSystemService(NotificationManager::class.java)
        nm.createNotificationChannel(NotificationChannel("relay", "Laptop connection", NotificationManager.IMPORTANCE_LOW))
        val open = PendingIntent.getActivity(
            this, 0, Intent(this, MainActivity::class.java), PendingIntent.FLAG_IMMUTABLE,
        )
        return Notification.Builder(this, "relay")
            .setSmallIcon(android.R.drawable.sym_action_call)
            .setContentTitle("Laptop Dialer")
            .setContentText(text)
            .setContentIntent(open)
            .setOngoing(ongoing)
            .build()
    }
}

