package com.laptopdialer

import android.content.Context
import org.json.JSONObject
import java.net.HttpURLConnection
import java.net.URL

// Blocking HTTP; call from a background thread.
object Api {
    // ponytail: plain app-private prefs for the JWT; move to Keystore-backed storage before Play release.
    fun prefs(ctx: Context) = ctx.getSharedPreferences("dialer", Context.MODE_PRIVATE)
    fun jwt(ctx: Context): String? = prefs(ctx).getString("jwt", null)

    fun post(path: String, body: JSONObject, jwt: String? = null): Pair<Int, String> {
        val conn = URL(BuildConfig.API_URL + path).openConnection() as HttpURLConnection
        try {
            conn.requestMethod = "POST"
            conn.connectTimeout = 10_000
            conn.readTimeout = 10_000
            conn.doOutput = true
            conn.setRequestProperty("Content-Type", "application/json")
            jwt?.let { conn.setRequestProperty("Authorization", "Bearer $it") }
            conn.outputStream.use { it.write(body.toString().toByteArray()) }
            val code = conn.responseCode
            val stream = if (code < 400) conn.inputStream else conn.errorStream
            return code to (stream?.bufferedReader()?.use { it.readText() } ?: "")
        } finally {
            conn.disconnect()
        }
    }

    fun registerDevice(ctx: Context, fcm[redacted] Int {
        val jwt = jwt(ctx) ?: return 401
        return post("/api/devices", JSONObject().put("fcm_token", fcmToken), jwt).first
    }

    fun report(ctx: Context, callId: String, status: String, durationS: Int = 0) {
        runCatching {
            post("/api/calls/$callId", JSONObject().put("status", status).put("duration_s", durationS), jwt(ctx))
        }
    }
}

