  await report({ status: "dialing" });
  await report({ status: "ended", duration_s: 42 });
  console.log("phone: reported");
};
ws.onerror = (e) => console.log("phone: error", e.message ?? e.type);
ws.onclose = (e) => console.log("phone: closed", e.code);
setTimeout(() => process.exit(0), 8000);
EOF
